/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"ableton-level-7","number":7,"title":"Record Capture Comp Bounce Route Mix","skillBand":"Textbook","duration":"From the course textbook","summary":"- Gate ID: ableton-gate-d - Prerequisites: Module 7 (Sections 7.1–7.4)","modules":[{"id":"ableton-m-GD-1","code":"GD","title":"Readiness Assessment: Gate D","blurb":"- Gate ID: ableton-gate-d - Prerequisites: Module 7 (Sections 7.1–7.4)","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-gate-d","title":"Section overview","blocks":[{"type":"step","title":"Tracking, Comping, Routing Architecture & Summing Subsystems","blocks":[{"type":"heading","text":"Assessment Overview","level":3},{"type":"list","items":["<strong>Gate ID:</strong> <code>ableton-gate-d</code>","<strong>Prerequisites:</strong> Module 7 (Sections 7.1–7.4)","<strong>Evaluation Format:</strong> Deterministic Self-Assessment Protocol (Direct execution in Ableton Live 12 Standard)","<strong>Objective:</strong> Verify operational mastery in low-latency tracking, monitoring states, retrospective Capture MIDI, multi-lane vocal comping, in-session audio bouncing, sidechain busing, and nested group mixer architecture."],"ordered":false},{"type":"heading","text":"Verification Drill Protocol","level":3},{"type":"prose","html":"Execute the following four operational drills in Ableton Live 12 Standard:"},{"type":"heading","text":"Drill 1: Monitoring Modes & Retrospective Capture","level":4},{"type":"list","items":["Configure an audio track: test <code>In</code>, <code>Auto</code>, and <code>Off</code> monitoring modes with live microphone or line input. Explain out loud why <code>Off</code> is required when using hardware zero-latency interface monitoring.","On a MIDI track hosting Operator or Drift, improvise an unrecorded 4-bar performance with transport stopped.","Press <code>Ctrl+Shift+C</code> (<strong>Capture MIDI</strong>). Verify that Live recovers the exact phrase into a new MIDI clip."],"ordered":true},{"type":"heading","text":"Drill 2: Multitrack Comping","level":4},{"type":"list","items":["Set the Arrangement Loop Brace across bars <code>1.1</code> to <code>5.1</code>.","Record 3 continuous loop takes of a vocal or solo melodic line onto an audio track.","Open Take Lanes (<code>Ctrl+Alt+U</code>).","Audition each take lane using the lane solo speaker icon (<code>🔊</code>).","Use Draw Mode (<code>B</code>) to splice and promote the best regions from all 3 takes into the active Main Track Lane."],"ordered":true},{"type":"heading","text":"Drill 3: Internal Busing & Sidechain Ducking","level":4},{"type":"list","items":["Create a Drum track containing a 4-on-the-floor kick pattern.","Create a Synth Pad track hosting a sustained pad sound.","Insert a native <strong>Compressor</strong> onto the Synth Pad track.","Enable the Compressor's <strong>Sidechain</strong> section. Set <strong>Audio From</strong> to the Kick track (<code>Post-FX</code>).","Adjust Threshold to -18 dB, Ratio to 4:1, Attack to 2.0 ms, and Release to 100 ms. Verify audible ducking of the pad upon every kick stroke."],"ordered":true},{"type":"heading","text":"Drill 4: Nested Submix Architecture & In-Session Bouncing","level":4},{"type":"list","items":["Create 4 drum tracks (<code>Kick</code>, <code>Snare</code>, <code>Hats</code>, <code>Percussion</code>).","Group Hats and Percussion into a sub-group (<code>Hats_Perc_Sub</code>).","Group Kick, Snare, and <code>Hats_Perc_Sub</code> into a parent stem group (<code>DRUM_STEM</code>).","Right-click the <code>DRUM_STEM</code> group header and select <strong>Bounce Tracks to Audio</strong>.","Verify that a new audio track is generated containing the rendered stereo submix of the entire drum kit."],"ordered":true}]}],"minutes":8},{"id":"ableton-gate-d-2","title":"D Verification Checklist & Sign-Off","blocks":[{"type":"step","title":"D Verification Checklist & Sign-Off","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[GATE D PASS CRITERIA]\n[ ] Drill 1 Complete: Monitoring modes verified; Capture MIDI executed from circular buffer.\n[ ] Drill 2 Complete: 3-lane audio comp assembled in the Main Track Lane.\n[ ] Drill 3 Complete: Internal sidechain ducking routed from kick to pad compressor.\n[ ] Drill 4 Complete: 2-tier nested group constructed; drum stem bounced to audio.</pre>"},{"type":"prose","html":"<strong>Status:</strong> When all criteria are checked, the student is certified for Module 8: Automation, Clip Envelopes, Racks, Plug-ins &amp; Video."}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-7-1-2","code":"7.1","title":"Record, Capture, Comp, Bounce, Route & Mix","blurb":"- Section ID: ableton-sec-7-1 - Lessons Included: ableton-l7-1-1, ableton-l7-1-2, ableton-l7-1-3","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l7-1-1","title":"Section overview","blocks":[{"type":"step","title":"Section 7.1 — I/O Matrix, Monitoring States, Resampling & Internal Routing","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-7-1</code>","<strong>Lessons Included:</strong> <code>ableton-l7-1-1</code>, <code>ableton-l7-1-2</code>, <code>ableton-l7-1-3</code>","<strong>Target Skill Band:</strong> Advanced Signal Routing &amp; Studio Patching","<strong>Manual Spine References:</strong> Chapter 17 (<em>Routing and I/O: 17.1–17.7</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard Audio/MIDI Matrix Architecture"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Configure Physical Audio &amp; MIDI I/O:</strong> Route physical mono and stereo hardware inputs, assign hardware outputs, and configure MIDI ports for zero-latency tracking.","<strong>Master the Three Monitoring States:</strong> Differentiate <strong>In</strong>, <strong>Auto</strong>, and <strong>Off</strong> monitoring modes, diagnosing double-monitoring phasing and tracking latency anomalies.","<strong>Execute Internal Bus Routing &amp; Resampling:</strong> Route audio from track-to-track, tap pre-FX/post-FX/post-mixer signal points, and utilize the master <strong>Resampling</strong> engine to record live session summing.","<strong>Construct Sidechain Trigger Signal Paths:</strong> Establish internal routing architectures to feed sidechain detector inputs on compressors and gates."],"ordered":true}]}],"minutes":8},{"id":"ableton-l7-1-1-2","title":"7.1.1: Monitoring Architecture: In vs. Auto vs. Off","blocks":[{"type":"step","title":"1.1 The Monitoring States Defined","blocks":[{"type":"prose","html":"Located in the In/Out (I/O) section of every track mixer strip (<code>Ctrl+Alt+I</code>):"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                          TRACK MONITORING MODES                             │\n├─────────┬──────────────────────────────────┬────────────────────────────────┤\n│ MODE    │ BEHAVIOR WHEN ARMED (●)          │ BEHAVIOR WHEN UNARMED          │\n├─────────┼──────────────────────────────────┼────────────────────────────────┤\n│ **In**  │ Listens ONLY to live physical/   │ Listens ONLY to live physical/ │\n│         │ internal input. Clip playback is │ internal input. Clip playback  │\n│         │ completely MUTED on this track.  │ is completely MUTED.           │\n├─────────┼──────────────────────────────────┼────────────────────────────────┤\n│ **Auto**│ When armed: Listens to live      │ When unarmed: Listens ONLY to  │\n│(Default)│ input (monitoring live perf.).   │ playing clips on the track.    │\n│         │ When playing back: auto-switches.│                                │\n├─────────┼──────────────────────────────────┼────────────────────────────────┤\n│ **Off** │ Listens ONLY to clips on track.  │ Listens ONLY to clips on track.│\n│         │ Zero software monitoring latency.│ Zero software monitoring.      │\n│         │ Ideal for hardware direct monitor│                                │\n└─────────┴──────────────────────────────────┴────────────────────────────────┘</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                     MONITORING ROUTING FLOWCHART                            │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [Audio Input (Mic/Line)] ──► [Track Input Chooser]                         │\n│                                      │                                      │\n│                                      ▼                                      │\n│  MONITOR MODE CHOOSER:                                                      │\n│  ├── [ In ]   ──► Passes direct to Device Chain ──► Mutes Clip Playback     │\n│  ├── [ Auto ] ──► If Armed: Passes Live Input   ──► Mutes Clip Playback     │\n│  │            ──► If Unarmed: Mutes Live Input  ──► Plays Track Clips       │\n│  └── [ Off ]  ──► Mutes Live Input entirely     ──► Plays Track Clips       │\n│                   (Use when using Hardware Interface Direct Monitoring)     │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"callout","variant":"key","title":"Note","html":"[!CAUTION] <strong>The Double-Monitoring Phasing Artifact:</strong> If you enable zero-latency direct hardware monitoring on your audio interface while Live's track monitor is set to <code>In</code> or <code>Auto</code>, you will hear the dry hardware signal summed with the slightly delayed software buffer signal. This produces severe comb filtering (metallic phasing). To resolve: mute hardware direct monitoring OR set Live's track monitor to <code>Off</code>."}]}],"minutes":8},{"id":"ableton-l7-1-2","title":"7.1.2: External MIDI Routing & Hardware Instruments","blocks":[{"type":"step","title":"2.1 MIDI In / MIDI Out Channel Allocation","blocks":[{"type":"list","items":["<strong>MIDI From Chooser:</strong> Selects the specific input device (e.g., <em>Novation Launchkey MK4</em>) and MIDI Channel (1 to 16). Set to <code>All Inputs / All Channels</code> for general keyboard tracking, or lock to a specific channel when using multi-channel MIDI splitters.","<strong>MIDI To Chooser:</strong> Routes outgoing MIDI note and CC data from the track directly to external hardware synthesizers, drum machines, or virtual MIDI loopback ports."],"ordered":false}]}],"minutes":8},{"id":"ableton-l7-1-3","title":"7.1.3: Resampling, Internal Taps & Sidechain Busing","blocks":[{"type":"step","title":"7.1.3: Resampling, Internal Taps & Sidechain Busing","blocks":[{"type":"heading","text":"3.1 The Resampling Engine","level":4},{"type":"prose","html":"Setting an audio track's <strong>Audio From</strong> chooser to <strong>Resampling</strong> routes the entire summed output of Live's Main Output Bus directly into that track's input:"},{"type":"list","items":["<strong>Use Case:</strong> Instantly records multi-track live improvisations, complex generative Max for Live modulation passes, or master output sound design into a pristine 32-bit floating-point audio clip."],"ordered":false},{"type":"heading","text":"3.2 Internal Signal Taps: Pre-FX, Post-FX & Post-Mixer","level":4},{"type":"prose","html":"When routing Audio From another track (e.g., Track 1 -&gt; Track 2), Live exposes three distinct tapping points:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                          INTERNAL SIGNAL TAPPING                            │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [TRACK 1]                                                                  │\n│  [Raw Audio Clip] ──► (1) PRE-FX TAP                                        │\n│                            │                                                │\n│                            ▼                                                │\n│  [Device Chain (EQ/Dist)] ──► (2) POST-FX TAP                               │\n│                                    │                                        │\n│                                    ▼                                        │\n│  [Volume Fader / Pan / Mute] ──► (3) POST-MIXER TAP                         │\n│                                           │                                 │\n│                                           ▼                                 │\n│                                    [Main Bus Output]                        │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong>Pre-FX:</strong> Taps the raw audio before entering any instruments or audio effects on the source track.","<strong>Post-FX:</strong> Taps the audio after processing by all devices on the track, but <em>before</em> the track volume fader, pan pot, and mute switch.","<strong>Post-Mixer:</strong> Taps the final signal after volume attenuation and panning."],"ordered":true},{"type":"heading","text":"3.3 Sidechain Routing Architecture","level":4},{"type":"prose","html":"Sidechaining uses an auxiliary audio signal to drive the level detection circuit of a dynamics processor:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                        SIDECHAIN ROUTING TOPOLOGY                           │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [Track 1: Kick Drum] ──► Audio Output ──► Main Bus                         │\n│           │                                                                 │\n│           └──► (Sidechain Key Signal Tap: Post-FX)                          │\n│                      │                                                      │\n│                      ▼                                                      │\n│  [Track 2: Synth Pad]                                                       │\n│  [Synth Engine] ──► [COMPRESSOR (Sidechain Enabled)] ──► [Pad Audio Out]    │\n│                     • Audio In: Synth Pad Audio                             │\n│                     • Detector Input: Track 1 (Kick)                        │\n│                     • Result: Pad ducks in volume upon every kick transient.│\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Internal Bus Routing &amp; Submix Printing Drill:</strong>","Create two audio tracks: Track 1 (<code>Synth_Source</code>) and Track 2 (<code>Print_Bus</code>).","On Track 1, load <strong>Drift</strong> and insert a <strong>Delay</strong> and <strong>Reverb</strong>.","On Track 2, set <strong>Audio From</strong> to <code>1-Synth_Source</code>. Set the tap point to <code>Post-FX</code>.","Set Track 2 Monitor to <code>In</code>.","Arm Track 2 and hit record. Confirm that Track 2 records the fully processed synth signal with reverb and delay tails.","<strong>Master Resampling Drill:</strong>","Create an empty audio track named <code>Master_Resample</code>.","Set <strong>Audio From</strong> to <code>Resampling</code>. Set Monitor to <code>Off</code> (to avoid feedback loops).","Arm <code>Master_Resample</code> and launch a full 4-track Session scene.","Record 8 bars. Mute all original tracks and play back the single resampled audio clip to verify an exact identical replica of the master mix sum."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 7.0]\n[ ] Fluent with In, Auto, and Off monitoring behaviors under armed and unarmed states.\n[ ] Diagnosed and resolved double-monitoring phasing anomalies.\n[ ] Routed audio internally utilizing Pre-FX, Post-FX, and Post-Mixer taps.\n[ ] Executed a clean Master Resampling pass without feedback.\n[ ] Established an external Sidechain key routing to a Compressor.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 17 (<em>Routing and I/O: 17.1–17.7</em>).","<strong>Ableton Knowledgebase:</strong> <em>Understanding Monitoring in Live</em>, <em>Internal Routing and Submixing</em>, <em>Sidechaining in Ableton Live</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-7-2-3","code":"7.2","title":"Record, Capture, Comp, Bounce, Route & Mix","blurb":"- Section ID: ableton-sec-7-2 - Lessons Included: ableton-l7-2-1, ableton-l7-2-2, ableton-l7-2-3","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l7-2-1","title":"Section overview","blocks":[{"type":"step","title":"Section 7.2 — Tracking Protocols, Overdubbing & Capture MIDI","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-7-2</code>","<strong>Lessons Included:</strong> <code>ableton-l7-2-1</code>, <code>ableton-l7-2-2</code>, <code>ableton-l7-2-3</code>","<strong>Target Skill Band:</strong> Real-Time Tracking &amp; Retrospective MIDI Capture","<strong>Manual Spine References:</strong> Chapter 19 (<em>Recording New Clips: 19.1–19.10</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard Tracking &amp; Capture Subsystem"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Execute Linear &amp; Non-Linear Tracking Passes:</strong> Arm tracks, configure input routing, and execute recording passes in both Session View clip slots and Arrangement View timeline tracks.","<strong>Implement MIDI Overdub &amp; Step Recording:</strong> Layer MIDI performances non-destructively using <strong>MIDI Overdub</strong> (<code>+</code>), and program complex rhythmic lines using <strong>MIDI Step Recording</strong>.","<strong>Configure Tracking Utilities:</strong> Configure the Metronome (rhythm divisions, sound presets, count-in bars: <code>1 Bar</code>, <code>2 Bars</code>, <code>4 Bars</code>) and apply non-destructive <strong>Record Quantization</strong>.","<strong>Deploy Retrospective Capture MIDI:</strong> Utilize <strong>Capture MIDI</strong> (<code>Ctrl+Shift+C</code>) to reconstruct unrecorded improvisations after playback has ceased, extracting tempo, meter, and loop boundaries into empty or populated Live Sets."],"ordered":true}]}],"minutes":8},{"id":"ableton-l7-2-1-2","title":"7.2.1: Tracking Modes: Session, Arrangement, Overdub & Step Record","blocks":[{"type":"step","title":"1.1 Session vs. Arrangement Recording Architecture","blocks":[{"type":"list","items":["<strong>Session View Recording:</strong> Toggling the <strong>Session Record Button</strong> (circular icon in Control Bar / <code>Ctrl+Shift+F9</code>) records audio/MIDI into the highlighted clip slot on armed tracks. When the launch quantization boundary is reached, recording transitions into continuous playback loop mode.","<strong>Arrangement View Recording:</strong> Toggling the master <strong>Arrangement Record Button</strong> (<code>F9</code>) prints recorded data linearly across horizontal tracks on the timeline ruler."],"ordered":false}]},{"type":"step","title":"1.2 MIDI Overdubbing (+ Icon in Control Bar)","blocks":[{"type":"prose","html":"When recording into an existing MIDI clip:"},{"type":"list","items":["<strong>Overdub ON (<code>+</code> lit):</strong> Newly played notes are merged directly into the existing MIDI clip without erasing previously recorded notes. Essential for building multi-layered drum patterns (e.g., tracking kick and snare on pass 1, adding hi-hats on pass 2, adding toms on pass 3).","<strong>Overdub OFF:</strong> Newly played notes overwrite existing notes in the recording region."],"ordered":false}]},{"type":"step","title":"1.3 MIDI Step Recording","blocks":[{"type":"prose","html":"Step recording allows notes to be entered one step at a time without real-time performance pressure:"},{"type":"list","items":["Arm a MIDI track and create an empty MIDI clip.","Ensure the MIDI Note Editor is focused and the <strong>Preview</strong> (headphones icon) is lit.","Hold a chord or note on the MIDI keyboard.","Press the <strong>Right Arrow</strong> key on the computer keyboard to advance the insert marker by the active grid division, printing the notes for that duration."],"ordered":true}]}],"minutes":8},{"id":"ableton-l7-2-2","title":"7.2.2: Metronome, Count-In & Record Quantization","blocks":[{"type":"step","title":"2.1 Metronome Configuration Submenu","blocks":[{"type":"prose","html":"Clicking the small disclosure triangle next to the Metronome icon in the Control Bar reveals tracking settings:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                       METRONOME CONFIGURATION MENU                          │\n├───────────────────┬─────────────────────────────────────────────────────────┤\n│ PARAMETER         │ OPERATIONAL OPTIONS                                     │\n├───────────────────┼─────────────────────────────────────────────────────────┤\n│ Count-In          │ None, 1 Bar, 2 Bars, 4 Bars (Pre-roll count before rec) │\n│ Sound Preset      │ Classic (Default beep), Click, Wood (Acoustic click)    │\n│ Rhythm Division   │ Auto (Follows meter), 1/4, 1/8, 1/16, Triplet           │\n│ Enable in Cue Only│ Routes metronome exclusively to headphone Cue out 3/4   │\n└───────────────────┴─────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"2.2 Record Quantization","blocks":[{"type":"prose","html":"Located in <code>Edit -&gt; Record Quantization</code>:"},{"type":"list","items":["<strong>Function:</strong> Automatically snaps incoming MIDI note onsets to the specified metric grid division (e.g., <code>1/16 Quantization</code>) <em>during real-time recording</em>.","<strong>Precaution:</strong> Record Quantization permanently affects the initial placement of recorded notes. To preserve human feel, disable Record Quantization and apply non-destructive Groove templates or post-recording Quantize (<code>Ctrl+U</code>) with a percentage strength."],"ordered":false}]},{"type":"step","title":"2.3 File System Location of Recorded Audio","blocks":[{"type":"prose","html":"All audio recorded directly into Live is automatically written to the Project folder on disk: <code>[Project Root]/Samples/Recorded/</code> with the naming convention <code>[Track Name]_[Take Number]_[Date].wav</code>."}]}],"minutes":8},{"id":"ableton-l7-2-3","title":"7.2.3: Retrospective Capture MIDI","blocks":[{"type":"step","title":"7.2.3: Retrospective Capture MIDI","blocks":[{"type":"heading","text":"3.1 The Capture Engine Mechanics","level":4},{"type":"prose","html":"Live continuously maintains a circular MIDI input buffer in background memory for all armed or monitored MIDI tracks, even when transport playback is completely stopped:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                      CAPTURE MIDI OPERATIONAL PIPELINE                      │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  SCENARIO: Musician improvises an expressive phrase without pressing Record.│\n│                                                                             │\n│  1. ACTION: Musician presses [Ctrl+Shift+C] (Capture MIDI).                 │\n│                                                                             │\n│  2. ANALYSIS (Empty Set):                                                   │\n│     • Reconstructs the exact notes played from circular buffer.             │\n│     • Calculates the tempo of the performance mathematically.               │\n│     • Sets the global BPM to match the musician's natural tempo.            │\n│     • Establishes downbeat 1.1.1 and sets loop braces around the phrase.    │\n│                                                                             │\n│  3. ANALYSIS (Populated Set with Existing Tracks):                          │\n│     • Preserves existing global tempo and meter.                            │\n│     • Conforms the captured phrase to the active project grid.              │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Step Recording a Fast Arpeggio:</strong>","Create a MIDI track hosting <strong>Analog</strong> or <strong>Drift</strong>.","Create an empty 1-bar MIDI clip in Session View. Open Clip View (<code>Shift+Tab</code>).","Set the editing grid to <code>1/16</code> (<code>Ctrl+1</code>/<code>Ctrl+2</code>).","Click inside the piano roll at <code>1.1.1</code>.","On the Computer MIDI Keyboard, hold <code>A</code> (C3). Press <code>Right Arrow</code> twice (prints an 1/8th note C3).","Hold <code>D</code> (E3). Press <code>Right Arrow</code> twice. Hold <code>G</code> (G3). Press <code>Right Arrow</code> twice. Hold <code>K</code> (B3). Press <code>Right Arrow</code> twice.","Play back the clip. Verify a mathematically pristine 16th-note arpeggio.","<strong>Capture MIDI Retrospective Recovery Drill:</strong>","Create a clean MIDI track with Operator. Ensure the track is armed.","DO NOT PRESS RECORD OR PLAY.","Jam an expressive 4-bar keyboard riff on your controller or computer keyboard.","Stop playing. Press <code>Ctrl+Shift+C</code> (<strong>Capture MIDI</strong>).","Observe Live instantly generating a new MIDI clip containing your exact performance, complete with loop braces and downbeat alignment."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 7.1]\n[ ] Recorded audio and MIDI in both Session clip slots and Arrangement timeline tracks.\n[ ] Layered drum hits non-destructively using MIDI Overdub (+).\n[ ] Successfully step-recorded a phrase using keyboard arrow navigation.\n[ ] Configured Metronome Count-In and Sound settings.\n[ ] Executed retrospective recovery of an unrecorded improvisation via Capture MIDI (Ctrl+Shift+C).</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 19 (<em>Recording New Clips: 19.1–19.10</em>).","<strong>Ableton Knowledgebase:</strong> <em>Capture MIDI in Depth</em>, <em>MIDI Overdub and Step Recording Workflows</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-7-3-4","code":"7.3","title":"Record, Capture, Comp, Bounce, Route & Mix","blurb":"- Section ID: ableton-sec-7-3 - Lessons Included: ableton-l7-3-1, ableton-l7-3-2, ableton-l7-3-3","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l7-3-1","title":"Section overview","blocks":[{"type":"step","title":"Section 7.3 — Comping, Take Lanes, Bouncing & Commit Protocols","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-7-3</code>","<strong>Lessons Included:</strong> <code>ableton-l7-3-1</code>, <code>ableton-l7-3-2</code>, <code>ableton-l7-3-3</code>","<strong>Target Skill Band:</strong> Vocal Comping &amp; Production Commit Architecture","<strong>Manual Spine References:</strong> Chapter 20 (<em>Bounce to Audio</em>), Chapter 21 (<em>Comping: 21.1–21.5</em>), Chapter 37 (<em>Computer Audio Resources and Strategies</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard Comping &amp; Render Subsystem"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Operate Take Lanes &amp; Comping Interfaces:</strong> Record loop passes to generate <strong>Take Lanes</strong> automatically (<code>Ctrl+Alt+U</code>), audition takes via Speaker solo icons, and assemble master composite tracks using the <strong>Splice</strong> selection tool (<code>B</code>).","<strong>Execute In-Session Audio Bouncing:</strong> Render individual tracks and group submixes directly to audio tracks using <strong>Bounce Tracks to Audio</strong> and the paste-bounced-audio protocol.","<strong>Select the Deterministic Commit Pathway:</strong> Systematically evaluate and apply <strong>Freeze</strong>, <strong>Flatten</strong>, <strong>Bounce</strong>, and <strong>Export</strong>, differentiating CPU management from irreversible mixing commits and final delivery mastering."],"ordered":true}]}],"minutes":8},{"id":"ableton-l7-3-1-2","title":"7.3.1: Take Lanes & Composite Editing (\"Comping\")","blocks":[{"type":"step","title":"1.1 Take Lane Architecture","blocks":[{"type":"prose","html":"When recording in Arrangement View with the <strong>Arrangement Loop</strong> active, each completed cycle of the loop automatically writes into a new, nested <strong>Take Lane</strong> beneath the main track lane:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                          COMPING &amp; TAKE LANE TOPOLOGY                       │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [MAIN TRACK LANE: Lead Vocal (Active Comp Output)]                         │\n│  [========================================================================] │\n│  │ Phrase 1 (From Take 1) │ Phrase 2 (From Take 3) │ Phrase 3 (From Take 2) │\n│  └────────────────────────┴────────────────────────┴────────────────────────┘\n│                                  ▲                                          │\n│                                  │ (Spliced selections promoted upward)     │\n│  ├── [TAKE LANE 1] [ 🔊 ] [Phrase 1 (Good)] [Phrase 2 (Flat)] [Phrase 3]    │\n│  ├── [TAKE LANE 2] [ 🔊 ] [Phrase 1]        [Phrase 2]        [Phrase 3 (G)]│\n│  └── [TAKE LANE 3] [ 🔊 ] [Phrase 1]        [Phrase 2 (Great)][Phrase 3]    │\n│                                                                             │\n│  • Toggle Take Lanes: Right-click track header -&gt; \"Show Take Lanes\"         │\n│  • Auditioning: Click the Speaker Icon [ 🔊 ] on any lane to solo that take │\n│  • Promotion: Highlight a region and press [Enter] or draw with Pencil (B)  │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong>Keyboard Shortcuts:</strong>","<code>Ctrl+Alt+U</code> / Right-click -&gt; <em>Show Take Lanes</em>.","Right-click Take Lane -&gt; <em>Insert Take Lane</em> (<code>Ctrl+Alt+I</code> while lane selected).","Press <code>B</code> to enable Draw Mode and drag across any take lane region to immediately splice and promote that region into the Main Comp Lane."],"ordered":false}]}],"minutes":8},{"id":"ableton-l7-3-2","title":"7.3.2: In-Session Track & Group Bouncing","blocks":[{"type":"step","title":"2.1 The Bounce to Audio Engine","blocks":[{"type":"prose","html":"Live provides direct in-session track rendering without forcing the user through the global export menu:"},{"type":"list","items":["<strong>Individual Track Bounce:</strong> Right-click an audio or MIDI track header and select <strong>Bounce Tracks to Audio</strong> (or select a group track to render a combined submix stem).","<strong>Behavior:</strong> Live renders the processed audio of the selected track(s) including all active device chain effects and automation, creating a new audio track immediately below with the rendered waveform positioned precisely on the grid.","<strong>Copy/Paste Bounced Audio:</strong> Selecting a region of an active track, pressing <code>Ctrl+C</code>, and pasting (<code>Ctrl+V</code>) onto a blank audio track automatically renders that specific selection to audio."],"ordered":false}]}],"minutes":8},{"id":"ableton-l7-3-3","title":"7.3.3: The Four Commit Pathways Compared","blocks":[{"type":"step","title":"7.3.3: The Four Commit Pathways Compared","blocks":[{"type":"prose","html":"Engineers must choose their commit strategy based on technical necessity rather than habit:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                       COMMIT PATHWAYS DECISION MATRIX                       │\n├─────────┬──────────────────────┬─────────────────────┬──────────────────────┤\n│ METHOD  │ PRIMARY OBJECTIVE    │ REVERSIBILITY       │ CPU RELIEF FACTOR    │\n├─────────┼──────────────────────┼─────────────────────┼──────────────────────┤\n│ Freeze  │ Temporary CPU relief │ 100% Reversible     │ Instant 100% relief  │\n│ Track   │ during active mixing │ (Click \"Unfreeze\")  │ for that track's DSP.│\n├─────────┼──────────────────────┼─────────────────────┼──────────────────────┤\n│ Flatten │ Permanent commit of  │ Irreversible        │ Permanently locks DSP│\n│ Track   │ frozen track to raw  │ (Requires Undo or   │ and removes plugins; │\n│         │ audio clips          │ backup .als)        │ zero CPU load.       │\n├─────────┼──────────────────────┼─────────────────────┼──────────────────────┤\n│ Bounce  │ Rendering stems or   │ Preserves original  │ Creates new audio    │\n│ Track   │ submixes while       │ live track intact   │ track; original live │\n│         │ keeping MIDI live    │ alongside bounce    │ track can be muted.  │\n├─────────┼──────────────────────┼─────────────────────┼──────────────────────┤\n│ Export  │ Generating final     │ Output rendered to  │ External file output;│\n│ Audio   │ stereo master / stem │ disk outside the    │ does not modify the  │\n│ (Ctrl+R)│ package for delivery │ active Live Project │ internal Set.        │\n└─────────┴──────────────────────┴─────────────────────┴──────────────────────┘</pre>"}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Vocal / Synth Comping Protocol:</strong>","Create an audio track named <code>Lead_Comp</code>.","Set the Arrangement Loop Brace across a 4-bar vocal or synth phrase (<code>bars 1.1 to 5.1</code>).","Arm the track and record 3 continuous loop passes without stopping.","Stop transport. Right-click the track header and select <strong>Show Take Lanes</strong>.","Click the speaker icon on Take Lane 1, then Take Lane 2, then Take Lane 3 to audition individual takes.","Press <code>B</code> to enable Draw Mode. Highlight bars 1–2 on Take 1, bar 3 on Take 3, and bar 4 on Take 2.","Notice the main composite track lane instantly assembling your edited master take.","<strong>Track Freezing &amp; Flattening Protocol:</strong>","On a CPU-heavy Operator or Analog track with heavy reverb, right-click the track header and select <strong>Freeze Track</strong>.","Observe the track turning frosty blue; CPU load drops to near zero.","Right-click the frozen track header and select <strong>Flatten</strong>. Confirm that the track converts into a raw audio track."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 7.2]\n[ ] Recorded multiple loop passes and revealed Take Lanes (Ctrl+Alt+U).\n[ ] Auditioned individual take lanes using the speaker solo icon.\n[ ] Assembled a seamless composite performance in the Main Track Lane.\n[ ] Executed Freeze Track and Flatten Track commands.\n[ ] Defined the architectural difference between Freezing, Bouncing, and Exporting.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 20 (<em>Bounce to Audio</em>), Chapter 21 (<em>Comping: 21.1–21.5</em>), Chapter 37 (<em>Computer Audio Resources and Strategies: 37.1 Track Freeze</em>).","<strong>Ableton Knowledgebase:</strong> <em>Comping in Live 11 and 12</em>, <em>Committing Audio: Freeze, Flatten, and Bounce</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-7-4-5","code":"7.4","title":"Record, Capture, Comp, Bounce, Route & Mix","blurb":"- Section ID: ableton-sec-7-4 - Lessons Included: ableton-l7-4-1, ableton-l7-4-2, ableton-l7-4-3","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l7-4-1","title":"Section overview","blocks":[{"type":"step","title":"Section 7.4 — Mixer Architecture, Nested Groups, Return Buses & Master Summing","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-7-4</code>","<strong>Lessons Included:</strong> <code>ableton-l7-4-1</code>, <code>ableton-l7-4-2</code>, <code>ableton-l7-4-3</code>","<strong>Target Skill Band:</strong> Advanced Mixing Architecture &amp; Summing Bus Topology","<strong>Manual Spine References:</strong> Chapter 18 (<em>Mixing: 18.1–18.8</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard Mixer Subsystem (12 Return Tracks, Nested Groups, 64-bit Summing)"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Operate the Unified Channel Strip:</strong> Navigate volume faders, pan pots, mute/activator switches, peak/RMS metering, and track delays (<code>D</code>).","<strong>Implement Hierarchical Nested Groups:</strong> Group related tracks (<code>Ctrl+G</code>), nest sub-groups within master stem buses (e.g., <code>All Drums</code> -&gt; <code>Cymbals &amp; Hats</code>), and extract individual chains to independent tracks.","<strong>Configure the 12 Auxiliary Return Buses:</strong> Route track sends to auxiliary returns (Returns A through L), manage return track pre/post fader routing, and master the <strong>Solo vs. Cue</strong> headphone auditioning subsystem.","<strong>Deploy the A/B Performance Crossfader:</strong> Assign tracks and returns to Crossfader Assign A/B and program crossfader curves for live performance transitions."],"ordered":true}]}],"minutes":8},{"id":"ableton-l7-4-1-2","title":"7.4.1: Channel Strip Architecture & Track Delay","blocks":[{"type":"step","title":"1.1 The Mixer Channel Strip Anatomy","blocks":[{"type":"prose","html":"Accessible in both Session View (vertical channel strips) and Arrangement View (horizontal track headers):"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                         MIXER CHANNEL STRIP ANATOMY                         │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [ Track Title Bar ]      Track 1 - \"Kick 808\"                              │\n│  [ In/Out Matrix ]        Audio From: Ext In 1 ──► Audio To: Group Drums    │\n│  [ Send Knobs (A - L) ]   [Send A: -inf] [Send B: -18dB] [Send C: -inf]     │\n│  [ Pan Control ]          &lt; C &gt; (Balance Stereo / Split Stereo Pan Mode)    │\n│  [ Volume Fader ]         [===|=======] -3.5 dBFS (Double-click resets 0dB) │\n│  [ Peak Meter ]           Dual LED ladder with orange clipping threshold    │\n│  [ Solo / Cue (S) ]       Blue Solo button (Auditions track in isolation)   │\n│  [ Track Activator (1) ]  Yellow Mute button (1 = Active / Dark = Muted)    │\n│  [ Record Arm (●) ]       Red Arm button (Routes live input to track)       │\n│  [ Track Delay (D) ]      [ 0.00 ms ] (Offsets track timing +/- ms or smp)  │\n│  [ Performance Impact ]   Real-time CPU footprint indicator per track       │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"1.2 Track Delay (D)","blocks":[{"type":"list","items":["<strong>Function:</strong> Applies an intentional millisecond or audio sample time offset (positive or negative) to an individual track.","<strong>Use Case:</strong> Aligning phase relationships between multi-mic acoustic instruments, compensating for slow analog synth envelope attacks, or shifting hi-hats slightly behind the beat for a relaxed groove pocket."],"ordered":false}]}],"minutes":8},{"id":"ableton-l7-4-2","title":"7.4.2: Hierarchical Nested Group Tracks","blocks":[{"type":"step","title":"2.1 Nested Group Bus Topologies","blocks":[{"type":"prose","html":"Live 12 allows tracks to be grouped into submix buses, and allows groups to be nested inside parent groups up to multiple hierarchical tiers:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                    HIERARCHICAL NESTED GROUP TOPOLOGY                       │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [PARENT GROUP: ALL DRUMS (Master Drum Bus Processing: Glue + EQ)]          │\n│  ├── [Track 1: Kick Direct]                                                 │\n│  ├── [Track 2: Snare Direct]                                                │\n│  └── ┌──────────────────────────────────────────────────────────────────┐   │\n│      │ [NESTED SUB-GROUP: HATS &amp; CYMBALS (Submix Processing: Dynamic Tube]│   │\n│      │ ├── [Track 3: Closed Hat]                                        │   │\n│      │ ├── [Track 4: Open Hat]                                          │   │\n│      │ └── [Track 5: Ride Cymbal]                                       │   │\n│      └──────────────────────────────────────────────────────────────────┘   │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong>Creating Groups:</strong> Select multiple tracks and press <code>Ctrl+G</code>.","<strong>Nesting Groups:</strong> Select existing group headers and press <code>Ctrl+G</code> to create a parent stem bus.","<strong>Extracting Tracks:</strong> Drag a track header out of the group container, or right-click and select <em>Ungroup</em>."],"ordered":false}]}],"minutes":8},{"id":"ableton-l7-4-3","title":"7.4.3: Returns, Main Bus, Crossfader & Cueing","blocks":[{"type":"step","title":"7.4.3: Returns, Main Bus, Crossfader & Cueing","blocks":[{"type":"heading","text":"3.1 Auxiliary Return Buses (Up to 12 Returns)","level":4},{"type":"list","items":["<strong>Architecture:</strong> Live 12 Standard supports up to <strong>12 dedicated Return Tracks</strong> (<code>Ctrl+Alt+T</code>), labeled Return A through Return L.","<strong>Send Routing:</strong> Each audio and MIDI track features discrete send pots corresponding to every active return.","<strong>Pre / Post Fader Sends:</strong> Right-click any send knob to toggle between <strong>Post-Fader</strong> (default; send level follows track fader movements) and <strong>Pre-Fader</strong> (send level remains constant regardless of track fader attenuation, ideal for independent headphone cue mixes or dub echo throws)."],"ordered":false},{"type":"heading","text":"3.2 Solo vs. Cue Subsystem","level":4},{"type":"list","items":["<strong>Solo Mode (<code>S</code> on tracks):</strong> Silences all other tracks, passing only the soloed track through the Main Output bus to the studio monitors.","<strong>Cue Mode (Headphone Preview):</strong> In the Main track mixer strip, toggling the <strong>Solo/Cue</strong> switch converts solo buttons into blue headphone <strong>Cue</strong> buttons.","<strong>Cue Operation:</strong> Clicking a Cue button routes that track directly to the secondary <strong>Cue Out</strong> physical output pair (e.g., Output 3/4 feeding the DJ/engineer headphones) without interrupting the Main Output 1/2 house mix."],"ordered":false},{"type":"heading","text":"3.3 The A/B Performance Crossfader","level":4},{"type":"list","items":["<strong>Assignment:</strong> Toggling the <strong>X</strong> button in the lower right of the mixer displays Crossfader Assign selectors (<code>A</code> or <code>B</code>) on all tracks and returns.","<strong>Crossfader Curves:</strong> Right-click the horizontal crossfader to select transition curves: <em>Transition</em> (linear fade), <em>Smooth</em> (constant power), or <em>Constant Hit</em> (fast cut for scratch routines)."],"ordered":false}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Building a Professional Drum Submix Hierarchy:</strong>","Create 4 tracks: <code>Kick</code>, <code>Snare</code>, <code>Closed_Hat</code>, <code>Ride</code>.","Select <code>Closed_Hat</code> and <code>Ride</code>; press <code>Ctrl+G</code>. Rename group to <code>Cymbals_Sub</code>.","Select <code>Kick</code>, <code>Snare</code>, and <code>Cymbals_Sub</code>; press <code>Ctrl+G</code>. Rename parent group to <code>ALL_DRUMS</code>.","On the <code>ALL_DRUMS</code> group bus, insert a <strong>Glue Compressor</strong> with 2:1 ratio, 30ms attack, and Auto release to knit the kit together.","<strong>Configuring Parallel Return Processing:</strong>","Insert Return Track A (<code>Reverb</code>) and Return Track B (<code>Delay</code>).","Turn Send A on the <code>Snare</code> track to <code>-12.0 dB</code>.","Turn Send B on a lead synth track to <code>-18.0 dB</code>.","Right-click Send B and select <strong>Pre-Fader</strong>. Pull the lead synth volume fader completely down to - dB. Observe that the delay echo continues ringing through Return B even though the dry synth is muted."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 7.3]\n[ ] Fluent with track channel strip controls and Track Delay (D).\n[ ] Built a 2-tier hierarchical Nested Group track architecture.\n[ ] Configured Return tracks and toggled Pre-Fader vs. Post-Fader send states.\n[ ] Operated the Solo vs. Cue headphone routing matrix.\n[ ] Assigned tracks to Crossfader A/B and auditioned transition curves.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 18 (<em>Mixing: 18.1 Mixer Controls, 18.2 Groups, 18.3 Returns, 18.4 Main Track, 18.5 Solo and Cueing, 18.6 Crossfader</em>).","<strong>Ableton Knowledgebase:</strong> <em>Using Group Tracks in Live</em>, <em>Setting up Cueing and Headphone Mixes</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
